mapper.select:
SELECT k.*, (CASE WHEN k.destination = #{destination} THEN 3 ELSE 0 END + CASE WHEN k.doc_type = 'guide' THEN 1 ELSE 0 END + COALESCE(k.sort_weight, 0)::numeric / 1000) AS match_score FROM t_knowledge_doc k WHERE k.deleted = 0 AND k.status = 'approved' AND ( k.destination = #{destination}
OR
k.title ILIKE '%' || #{kw} || '%' OR k.content ILIKE '%' || #{kw} || '%'
) ORDER BY match_score DESC, k.sort_weight DESC, k.id DESC LIMIT #{limit}
